[CreateAssetMenu(menuName = "Game/Score Calculator", fileName = "ScoreCalculator")]
public class ScoreCalculator : ScriptableObject
{
    [Header("閬撳叿鍒嗘暟")]
    [Tooltip("姣?1 ATP 閬撳叿浠锋牸 = 澶氬皯鍒?)]
    public float itemPriceMultiplier = 2f;

    [Header("鍑绘潃鍒嗘暟")]
    [Tooltip("姣忎釜鏅€氭晫浜哄嚮鏉€鍩虹鍒?)]
    public float killBaseScore = 100f;
    [Tooltip("Boss 鍑绘潃棰濆鍔犲垎锛堝悕瀛楀寘鍚?'Boss' 鏃惰Е鍙戯級")]
    public float bossKillBonus = 500f;

    [Header("閲戦挶鍒嗘暟")]
    [Tooltip("姣忚幏寰?1 ATP = 澶氬皯鍒?)]
    public float currencyEarnedMultiplier = 0.5f;
    [Tooltip("姣忔秷璐?1 ATP 鐨勬儵缃氬垎")]
    public float currencySpentPenalty = 0.3f;

    [Header("鎴块棿鍒嗘暟")]
    [Tooltip("姣忚繘鍏ヤ竴涓埧闂?)]
    public float roomVisitedScore = 50f;
    [Tooltip("姣忔竻绌轰竴涓埧闂?(棰濆)")]
    public float roomClearedBonus = 100f;

    [Header("鍩虹鍒?)]
    [Tooltip("淇濆簳鍩虹鍒?)]
    public float baseScore = 0f;

    // ==================== 璁＄畻 ====================

    /// <summary>鏍规嵁缁熻鏁版嵁璁＄畻鎬诲垎</summary>
    public int CalculateScore(GameStatistics stats)
    {
        if (stats == null) return 0;

        float total = baseScore;

        // 閬撳叿鍒? 危(item.price 脳 itemPriceMultiplier)
        float itemScore = 0f;
        foreach (var item in stats.AcquiredItems)
        {
            itemScore += item.price * itemPriceMultiplier;
        }
        total += itemScore;

        // 鍑绘潃鍒? 危(killCount 脳 baseScore) + Boss鍑绘潃 脳 bossBonus
        float killScore = 0f;
        foreach (var kvp in stats.EnemiesKilled)
        {
            float perKill = kvp.Key.Contains("Boss") || kvp.Key.Contains("boss")
                ? killBaseScore + bossKillBonus
                : killBaseScore;
            killScore += kvp.Value * perKill;
        }
        total += killScore;

        // 閲戦挶鍒?        total += stats.TotalCurrencyEarned * currencyEarnedMultiplier;
        total -= stats.TotalCurrencySpent * currencySpentPenalty;

        // 鎴块棿鍒?        total += stats.RoomsVisited * roomVisitedScore;
        total += stats.RoomsCleared * roomClearedBonus;

        return Mathf.Max(0, Mathf.RoundToInt(total));
    }
}
